/* Safelight local jsPDF-compatible runtime. Implements the subset used by Safelight; no network dependency. */
(function(global){
  'use strict';
  const te=new TextEncoder();
  const MM_TO_PT=72/25.4;
  function ascii(s){return te.encode(s)}
  function concat(parts){let len=0;for(const p of parts)len+=p.length;const out=new Uint8Array(len);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}
  function decodeDataUrl(url){const comma=url.indexOf(',');if(comma<0)throw new Error('Некорректное изображение');const meta=url.slice(0,comma),body=url.slice(comma+1);if(/;base64/i.test(meta)){const raw=atob(body),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}return te.encode(decodeURIComponent(body))}
  function jpegSize(bytes){
    if(bytes[0]!==0xff||bytes[1]!==0xd8)throw new Error('Для PDF нужен JPEG');let p=2;
    while(p+9<bytes.length){if(bytes[p]!==0xff){p++;continue}let marker=bytes[p+1];p+=2;while(marker===0xff){marker=bytes[p++]}if(marker===0xd8||marker===0xd9)continue;if(p+2>bytes.length)break;const len=(bytes[p]<<8)|bytes[p+1];if(len<2||p+len>bytes.length)break;if([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker)){return{height:(bytes[p+3]<<8)|bytes[p+4],width:(bytes[p+5]<<8)|bytes[p+6]}}p+=len
    }
    throw new Error('Не удалось определить размер JPEG');
  }
  function n(v){return Number(v).toFixed(3).replace(/\.000$/,'')}
  class jsPDF{
    constructor(options){options=options||{};const landscape=String(options.orientation||'portrait').toLowerCase().startsWith('l');this.pageW=landscape?297:210;this.pageH=landscape?210:297;this.image=null;this.internal={pageSize:{getWidth:()=>this.pageW,getHeight:()=>this.pageH}}}
    addImage(dataUrl,format,x,y,w,h){const bytes=decodeDataUrl(dataUrl);const size=jpegSize(bytes);this.image={bytes,widthPx:size.width,heightPx:size.height,x:+x||0,y:+y||0,w:+w||this.pageW,h:+h||this.pageH};return this}
    output(type){
      if(!this.image)throw new Error('Изображение не добавлено в PDF');const im=this.image,pw=this.pageW*MM_TO_PT,ph=this.pageH*MM_TO_PT,x=im.x*MM_TO_PT,w=im.w*MM_TO_PT,h=im.h*MM_TO_PT,y=ph-(im.y*MM_TO_PT)-h;
      const content=`q\n${n(w)} 0 0 ${n(h)} ${n(x)} ${n(y)} cm\n/Im0 Do\nQ\n`;
      const chunks=[],offsets=[0];let length=0;const push=b=>{chunks.push(b);length+=b.length};const obj=(id,body)=>{offsets[id]=length;push(ascii(`${id} 0 obj\n${body}\nendobj\n`))};
      push(new Uint8Array([0x25,0x50,0x44,0x46,0x2d,0x31,0x2e,0x34,0x0a,0x25,0xe2,0xe3,0xcf,0xd3,0x0a]));
      obj(1,'<< /Type /Catalog /Pages 2 0 R >>');
      obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
      obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${n(pw)} ${n(ph)}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);
      offsets[4]=length;push(ascii(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${im.widthPx} /Height ${im.heightPx} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${im.bytes.length} >>\nstream\n`));push(im.bytes);push(ascii('\nendstream\nendobj\n'));
      obj(5,`<< /Length ${ascii(content).length} >>\nstream\n${content}endstream`);
      const xref=length;let table='xref\n0 6\n0000000000 65535 f \n';for(let i=1;i<=5;i++)table+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';table+=`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;push(ascii(table));
      const out=concat(chunks);if(type==='arraybuffer')return out.buffer.slice(out.byteOffset,out.byteOffset+out.byteLength);if(type==='uint8array')return out;return new Blob([out],{type:'application/pdf'});
    }
  }
  global.jspdf={jsPDF};
})(window);
